function RulesDemo() {
 return (
 // Rule 1: ONE parent - using fragment <>
 <>
 {/* Rule 7: This is how you comment in JSX */}
 {/* Rule 2: className not class */}
 {/* Rule 3: Self-closed tags */}
 <h1 className="title">My Title</h1>
 <img src="logo.png" alt="Logo" />
 <br />
 {/* Rule 5: JS inside {} */}
 <p>{2 + 2} Rules Learned</p>
 {/* Rule 4: camelCase event */}
 <button onClick={() => alert('Clicked')}>Click</button>
 {/* Rule 6: Style as object */}
 <div style={{color: 'blue', backgroundColor: 'lightgray', padding: '10px'}}>
 Styled Box
 </div>
 </>
 );
}

function JSInsideJSX() {
 const name = "Prince";
 const age = 24;
 const isStudent = true;
 const skills = ["React", "JavaScript", "HTML"];

 function getGreeting() {
 return "Welcome to Code Academy";
 }

 return (
 <div>
 <h1>Hello {name}</h1> {/* Variable */}
 <p>Age next year: {age + 1}</p> {/* Calculation */}
 <p>{getGreeting()}</p> {/* Function call */}
 <p>{name.toUpperCase()}</p> {/* Method */}
 <p>{isStudent? "Student" : "Not Student"}</p> {/* Ternary - IF logic */}
 <p>Skills: {skills.join(", ")}</p> {/* Array method */}
 </div>
 );
}

function WrongExample() {
 return (
 <div>
 {/* ❌ WRONG - if statement directly inside JSX */}
 {/* {if(true) { <p>Hi</p> }} */}

 {/* ✅ CORRECT - Use ternary */}
 {true? <p>Hi</p> : <p>Bye</p>}

 {/* ❌ WRONG - for loop inside JSX */}
 {/* {for(let i=0; i<3; i++) { <p>{i}</p> }} */}

 {/* ✅ CORRECT - Use map outside or inside */}
 {[0,1,2].map(num => <p key={num}>{num}</p>)}
 </div>
 );
}

