// This structure scales to 100 components!

function LessonCard({ status }) {
 // status can be 'completed', 'current', 'locked'
 return (
 <div>
 <h3>React Lesson</h3>
 {/* Ternary for status badge */}
 {status === 'completed'? (
 <span style={{color: 'green'}}>✓ Completed</span>
 ) : status === 'current'? (
 <span style={{color: '#61dafb'}}>▶ Current</span>
 ) : (
 <span>🔒 Locked</span>
 )}

 {/* && operator - show button only if not locked */}
 {status!== 'locked' && <button>Start Lesson</button>}
 </div>
 );
}

function App() {
 return (
 <>
 <LessonCard status="completed" />
 <LessonCard status="current" />
 <LessonCard status="locked" />
 </>
 );
}

